export {};
declare function setTimeout(handler: () => void, timeout: number): NodeJS.Timeout;
declare function clearTimeout(handle: NodeJS.Timeout | undefined): void;
interface Slot {setTimeout?<A extends unknown[]>(callback: (...args: A) => void, ms: number, ...args: [...A, ...unknown[]]): unknown;clearTimeout?(id:unknown):void;}
declare const slot: Slot;
declare const queue: {pollScheduled: unknown};
slot.setTimeout!((_label:string, q:typeof queue)=>{},250,'label',queue);
slot.setTimeout!(()=>{},250,'pollQueue');
slot.setTimeout!(()=>{},1000,'timerToUpdateChildWatches');
const provider: Slot = {setTimeout,clearTimeout};

